"""Merge a list of integer [start, end] intervals.

Rules implemented:
  * intervals that overlap are merged;
  * intervals whose endpoints touch (``prev_end == next_start``) are merged;
  * the result is sorted by start (then end);
  * the input list and its inner pairs are never mutated;
  * a reversed pair (start > end) raises ``ValueError``.

Integer pairs that are merely adjacent but do not share an endpoint
(e.g. [1, 3] and [4, 5]) are NOT merged.
"""

from __future__ import annotations

__all__ = ["merge_intervals"]


def _as_pair(pair, index):
    """Validate one pair and return it as a plain ``(start, end)`` tuple."""
    if isinstance(pair, (str, bytes)) or not hasattr(pair, "__iter__"):
        raise TypeError(
            f"interval at index {index} must be a pair of integers, "
            f"got {type(pair).__name__!r}"
        )
    try:
        values = tuple(pair)
    except TypeError as exc:  # pragma: no cover - defensive
        raise TypeError(
            f"interval at index {index} is not iterable"
        ) from exc
    if len(values) != 2:
        raise TypeError(
            f"interval at index {index} must have exactly 2 values, "
            f"got {len(values)}"
        )
    start, end = values
    for value in (start, end):
        if isinstance(value, bool) or not isinstance(value, int):
            raise TypeError(
                f"interval at index {index} must contain integers, "
                f"got {value!r}"
            )
    if start > end:
        raise ValueError(
            f"reversed interval at index {index}: [{start}, {end}]"
        )
    return start, end


def merge_intervals(intervals):
    """Merge overlapping and touching ``[start, end]`` intervals.

    Args:
        intervals: iterable of ``[start, end]`` integer pairs.

    Returns:
        A new sorted list of merged ``[start, end]`` lists.

    Raises:
        TypeError: if an item is not a pair of integers.
        ValueError: if a pair is reversed (``start > end``).
    """
    if intervals is None:
        raise TypeError("intervals must be an iterable of [start, end] pairs")

    pairs = [_as_pair(pair, index) for index, pair in enumerate(intervals)]
    pairs.sort()

    merged = []
    for start, end in pairs:
        if merged and start <= merged[-1][1]:
            # overlaap or touching endpoint -> extend if needed
            if end > merged[-1][1]:
                merged[-1][1] = end
        else:
            merged.append([start, end])
    return merged

