"""Tests for solution.merge_intervals (stdlib unittest)."""

import copy
import unittest

from solution import merge_intervals


class TestMergeIntervals(unittest.TestCase):
    def test_overlapping(self):
        self.assertEqual(
            merge_intervals([[1, 4], [2, 6]]),
            [[1, 6]],
        )

    def test_touching_endpoints_merge(self):
        self.assertEqual(
            merge_intervals([[1, 3], [3, 5]]),
            [[1, 5]],
        )

    def test_adjacent_without_shared_endpoint_stay_separate(self):
        self.assertEqual(
            merge_intervals([[1, 2], [3, 4]]),
            [[1, 2], [3, 4]],
        )

    def test_unsorted_input(self):
        self.assertEqual(
            merge_intervals([[8, 10], [1, 3], [2, 5]]),
            [[1, 5], [8, 10]],
        )

    def test_nested(self):
        self.assertEqual(
            merge_intervals([[1, 10], [2, 3], [4, 5]]),
            [[1, 10]],
        )

    def test_disjoint_sorted_output(self):
        self.assertEqual(
            merge_intervals([[5, 7], [1, 2], [20, 21]]),
            [[1, 2], [5, 7], [20, 21]],
        )

    def test_single_interval(self):
        self.assertEqual(merge_intervals([[2, 2]]), [[2, 2]])

    def test_empty(self):
        self.assertEqual(merge_intervals([]), [])

    def test_iterator_input(self):
        self.assertEqual(merge_intervals(iter([[3, 4], [1, 2]])), [[1, 2], [3, 4]])

    def test_tuple_input(self):
        self.assertEqual(merge_intervals([(1, 3), (3, 4)]), [[1, 4]])

    def test_chain_touching(self):
        self.assertEqual(
            merge_intervals([[10, 11], [1, 2], [2, 3], [3, 4]]),
            [[1, 4], [10, 11]],
        )

    def test_negative_and_zero(self):
        self.assertEqual(
            merge_intervals([[-5, -3], [-3, 0], [1, 1]]),
            [[-5, 0], [1, 1]],
        )

    def test_duplicates(self):
        self.assertEqual(merge_intervals([[1, 3], [1, 3], [1, 3]]), [[1, 3]])

    def test_does_not_mutate_input(self):
        source = [[5, 8], [1, 3], [3, 4]]
        snapshot = copy.deepcopy(source)
        result = merge_intervals(source)
        self.assertEqual(source, snapshot)
        self.assertEqual(result, [[1, 4], [5, 8]])
        # mutating the result must not touch the input either
        result[0][1] = 999
        self.assertEqual(source, snapshot)

    def test_does_not_mutate_tuple_of_tuples(self):
        source = ((2, 4), (4, 6))
        merge_intervals(source)
        self.assertEqual(source, ((2, 4), (4, 6)))

    def test_reversed_pair_raises_value_error(self):
        with self.assertRaises(ValueError):
            merge_intervals([[3, 1]])

    def test_reversed_pair_raises_even_when_unsorted_neighbours_exist(self):
        with self.assertRaises(ValueError):
            merge_intervals([[1, 2], [9, 4], [10, 12]])

    def test_reversed_pair_error_names_index(self):
        with self.assertRaises(ValueError) as ctx:
            merge_intervals([[1, 2], [5, 3]])
        self.assertIn("1", str(ctx.exception))

    def test_none_raises_type_error(self):
        with self.assertRaises(TypeError):
            merge_intervals(None)

    def test_bad_shape_raises_type_error(self):
        with self.assertRaises(TypeError):
            merge_intervals([[1, 2, 3]])
        with self.assertRaises(TypeError):
            merge_intervals([[1]])

    def test_non_integer_raises_type_error(self):
        with self.assertRaises(TypeError):
            merge_intervals([[1.5, 2]])
        with self.assertRaises(TypeError):
            merge_intervals([["1", "2"]])


if __name__ == "__main__":
    unittest.main(verbosity=2)

