"""Decimal-exact ledger totals."""

from decimal import Decimal, InvalidOperation

__all__ = ["total"]


def _to_decimal(row):
    """Convert one row to an exact Decimal, or raise ValueError."""
    if row is None:
        raise ValueError("malformed numeric value: None")
    if isinstance(row, str):
        text = row.strip()
        if not text:
            raise ValueError("malformed numeric value: %r" % (row,))
        try:
            value = Decimal(text)
        except InvalidOperation:
            raise ValueError("malformed numeric value: %r" % (row,)) from None
    elif isinstance(row, bool):
        # bool is an int subclass; a flag is not a ledger amount.
        raise ValueError("malformed numeric value: %r" % (row,))
    elif isinstance(row, float):
        # str() avoids importing binary float noise into the total.
        value = Decimal(str(row))
    else:
        try:
            value = Decimal(row)
        except (InvalidOperation, TypeError, ValueError):
            raise ValueError("malformed numeric value: %r" % (row,)) from None
    if not value.is_finite():
        raise ValueError("malformed numeric value: %r" % (row,))
    return value


def total(rows):
    """Sum ledger rows as an exact Decimal.

    Signed amounts ("+1.50", "-2.00") are accepted, blank/whitespace-only
    lines are skipped, and malformed numeric values raise ValueError.
    """
    running = Decimal("0")
    for row in rows:
        if isinstance(row, str) and not row.strip():
            continue
        running += _to_decimal(row)
    return running

"""Ledger helpers.

`total` sums amounts exactly, using decimal.Decimal end to end, so
0.1 + 0.2 == 0.3 and currency values keep every digit.
"""

from decimal import Decimal, InvalidOperation

__all__ = ["total"]


def _to_decimal(value):
    """Convert one amount to Decimal, or raise ValueError if malformed."""
    if isinstance(value, Decimal):
        dec = value
    elif isinstance(value, str):
        text = value.strip()
        if not text:
            raise ValueError("blank value")
        # Reject things Decimal would refuse, and 1_000 / nan / inf too.
        try:
            dec = Decimal(text)
        except (InvalidOperation, ValueError):
            raise ValueError("malformed numeric value: %r" % (value,))
    elif isinstance(value, bool):
        raise ValueError("malformed numeric value: %r" % (value,))
    elif isinstance(value, int):
        dec = Decimal(value)
    elif isinstance(value, float):
        # Decimal(float) exposes binary noise; Decimal(str()) does not.
        try:
            dec = Decimal(str(value))
        except (InvalidOperation, ValueError):
            raise ValueError("malformed numeric value: %r" % (value,))
    else:
        raise ValueError("malformed numeric value: %r" % (value,))

    if not dec.is_finite():
        raise ValueError("malformed numeric value: %r" % (value,))
    return dec


def total(rows):
    """Exact decimal total of `rows`.

    - Blank lines (empty or whitespace-only strings) are ignored.
    - Signed amounts are accepted, including "-1.50" and "+2.25".
    - Any malformed numeric value raises ValueError, naming the value.
    - Returns a Decimal; raises TypeError if `rows` is not iterable.
    """
    result = Decimal(0)
    for row in rows:
        if isinstance(row, str):
            if not row.strip():
                continue
            result += _to_decimal(row)
        elif row is None:
            raise ValueError("malformed numeric value: None")
        elif isinstance(row, (list, tuple)):
            # A whole ledger row: blank row is skipped, else take the amount
            # from the last non-blank cell.
            cells = [c for c in row if not isinstance(c, str) or c.strip()]
            if not cells:
                continue
            result += _to_decimal(cells[-1])
        else:
            result += _to_decimal(row)
    return result

