import unittest
from decimal import Decimal

from ledger import total


class TestTotal(unittest.TestCase):
    def test_exact_decimals(self):
        self.assertEqual(total(["0.1", "0.2"]), Decimal("0.3"))
        self.assertEqual(total(["1.005", "2.005"]), Decimal("3.010"))

    def test_returns_decimal(self):
        self.assertIsInstance(total(["1", "2"]), Decimal)
        self.assertIsInstance(total([]), Decimal)
        self.assertEqual(total([]), Decimal("0"))

    def test_no_float_drift(self):
        self.assertEqual(total(["0.1"] * 10), Decimal("1.0"))
        # float math would give 0.30000000000000004
        self.assertEqual(str(total(["0.1", "0.2"])), "0.3")

    def test_signed_amounts(self):
        self.assertEqual(total(["-5.25", "+3", "1.25"]), Decimal("-1.00"))
        self.assertEqual(total(["-10", "10"]), Decimal("0"))

    def test_blank_lines_ignored(self):
        self.assertEqual(
            total(["1.5", "", "   ", "\t", "\n", "2.5"]),
            Decimal("4.0"),
        )
        self.assertEqual(total(["", "  "]), Decimal("0"))

    def test_numeric_types(self):
        self.assertEqual(total([1, 2, "3.5"]), Decimal("6.5"))
        self.assertEqual(total([0.5, 0.25]), Decimal("0.75"))

    def test_whitespace_padded_numbers_ok(self):
        self.assertEqual(total(["  2.50  ", "\t-0.50\t"]), Decimal("2.00"))

    def test_mixed_with_blanks(self):
        self.assertEqual(total(["10", "", "-2", " ", "0.5"]), Decimal("8.5"))

    def test_malformed_raises_value_error(self):
        bad_values = ["abc", "1.2.3", "1,000", "$5", "12abc", "--3", None, True, object()]
        for bad in bad_values:
            with self.assertRaises(ValueError, msg=repr(bad)):
                total([bad])

    def test_non_finite_rejected(self):
        for bad in ["nan", "NaN", "inf", "-Inf", Decimal("NaN"), Decimal("Infinity")]:
            with self.assertRaises(ValueError, msg=repr(bad)):
                total([bad])

    def test_error_does_not_swallow_earlier_rows(self):
        with self.assertRaises(ValueError):
            total(["1", "2", "oops", "3"])


if __name__ == "__main__":
    unittest.main(verbosity=2)
